#!/bin/bash
# Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# Comments and reviews go in pr-comments.md, never pr-context.md:
#   1. Conversation comments and review summaries come from the same
#      `gh pr view --json` call as the metadata.
#   2. Inline review comments come from the REST endpoint, and every page is
#      included — `--paginate` emits one array per page.
#   3. Bodies are written verbatim: a suggestion block is the reviewer's exact
#      proposed text, so reformatting or truncating it defeats the purpose.
#   4. A failed inline fetch is recorded in the file, so "no comments" and
#      "could not read the comments" stay distinguishable.
#   5. The authoritative file carries none of it. That separation is what lets
#      the prompt tell a session not to read the discussion at all.
#
# gh is stubbed, so the test needs no auth or network.
#
# Run: tests/test-pr-context-comments.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "${SCRIPT_DIR}/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null
export GIT_AUTHOR_NAME=test GIT_AUTHOR_EMAIL=test@example.com
export GIT_COMMITTER_NAME=test GIT_COMMITTER_EMAIL=test@example.com

source "${REPO_ROOT}/scripts/lib.sh"

fail=0

STUB="${TMP}/stub"
mkdir -p "$STUB"
cat > "${STUB}/gh" << 'STUBEOF'
#!/bin/bash
case "$1 $2" in
    "pr view")
        echo '{"number":12,"title":"t","body":"desc","headRefName":"feat","baseRefName":"main","labels":[],"assignees":[]}'
        ;;
    "pr list")
        echo '[]'
        ;;
    *)
        if [[ "$1" == "api" ]]; then
            [[ -n "${GH_API_BROKEN:-}" ]] && { echo "HTTP 502" >&2; exit 1; }
            # Resolution is GraphQL-only. Carol's thread is open, Dave's is
            # resolved, so both flags are exercised.
            if [[ "$2" == "graphql" ]]; then
                echo '{"data":{"repository":{"pullRequest":{"reviewThreads":{"pageInfo":{"hasNextPage":false,"endCursor":null},"nodes":[{"isResolved":false,"comments":{"nodes":[{"databaseId":1}]}},{"isResolved":true,"comments":{"nodes":[{"databaseId":2}]}}]}}}}}'
                exit 0
            fi
            path=""
            for api_arg in "$@"; do path="$api_arg"; done
            case "$path" in
                */issues/*/comments*)
                    echo '[{"user":{"login":"alice"},"created_at":"2026-11-01T09:05:00Z","body":"first comment\nsecond line"}]'
                    ;;
                */pulls/*/reviews*)
                    # Erin's review has no summary: its content is the inline
                    # comment that carries pull_request_review_id 102. It must
                    # be grouped under that review, not left as a header with
                    # nothing under it.
                    echo '[{"id":101,"user":{"login":"bob"},"state":"CHANGES_REQUESTED","submitted_at":"2026-11-02T10:15:00Z","body":"please fix\n\n```suggestion\nnew\n```"},{"id":102,"user":{"login":"erin"},"state":"COMMENTED","submitted_at":"2026-11-02T11:00:00Z","body":""}]'
                    ;;
                */pulls/*/comments*)
                    # Two pages, as `--paginate` emits them: separate arrays,
                    # one after the other. A fetch that parsed only the first
                    # would still pass a check that looked for one row.
                    # diff_hunk is the context that makes the comment readable:
                    # the original line, the proposed one, and surrounding
                    # lines. Both pages carry it.
                    echo '[{"id":1,"pull_request_review_id":102,"user":{"login":"carol"},"path":"a.sh","line":4,"created_at":"2026-11-03T11:00:00Z","diff_hunk":"@@ -1,3 +1,3 @@\n context line\n-old line\n+new line\n","body":"inline one"}]'
                    # No review claims this one: it must still appear, in its
                    # own section, rather than vanish.
                    echo '[{"id":2,"pull_request_review_id":999,"user":{"login":"dave"},"path":"b.sh","line":9,"created_at":"2026-11-04T12:30:00Z","diff_hunk":"@@ -7,3 +7,3 @@\n more context\n-another old\n+another new\n","body":"inline two"}]'
                    ;;
                *)
                    echo '[]'
                    ;;
            esac
            exit 0
        fi
        exit 1
        ;;
esac
STUBEOF
chmod +x "${STUB}/gh"
export PATH="${STUB}:${PATH}"

# --- fixture: one GitHub repo on a branch ---
SBX="${TMP}/sandbox"
REPO="${SBX}/myrepo"
mkdir -p "$REPO"
git -C "$REPO" init -q -b feat
echo x > "${REPO}/f"
git -C "$REPO" add f
git -C "$REPO" commit -qm init   # rev-parse HEAD must resolve
jq -n '{name:"probe",repos:{myrepo:{url:"git@github.com:org/myrepo.git"}}}' > "${SBX}/manifest.json"

CTX="${REPO}/pr-context.md"
DISCUSSION="${REPO}/pr-comments.md"
expect() {
    grep -qF -- "$1" "$DISCUSSION" \
        || { echo "FAIL: pr-comments.md missing: $1" >&2; fail=1; }
}
refute() {
    grep -qE "$1" "$CTX" \
        && { echo "FAIL: ${1} leaked into pr-context.md" >&2; fail=1; }
    return 0
}

generate_repo_context "$SBX" myrepo personal >/dev/null 2>&1 || true

# The banner is what a session sees if it opens the file anyway.
expect 'Discussion only. Not authoritative.'
# Authoritative file: description yes, discussion no.
grep -qF 'desc' "$CTX" || { echo "FAIL: pr-context.md lost the description" >&2; fail=1; }
refute 'first comment'
refute '### @bob'
refute 'inline one'
refute '^# PR Comments'

expect '## PR Comments (1)'
expect '### @alice — 2026-11-01 09:05'
expect 'first comment'
expect 'second line'

expect '## PR Reviews (2)'
expect '### @bob — CHANGES_REQUESTED — 2026-11-02 10:15'
expect 'please fix'
# The suggestion block is the actionable part of the review; a body that got
# flattened to one line would lose it while still matching "please fix".
expect '```suggestion'
expect '### @erin — COMMENTED — 2026-11-02 11:00'
# The review has no summary; its text is the inline comment directly under
# it. Grouping is what gives the comment its context.
# Thread state is GraphQL-only; REST has no such field. Without it a session
# cannot tell an open comment from one already resolved.
expect '#### a.sh:4 — unresolved'
expect 'inline one'
erin_line=$(grep -n '^### @erin' "$DISCUSSION" | cut -d: -f1)
inline_line=$(grep -n '^#### a\.sh:4' "$DISCUSSION" | cut -d: -f1)
[[ -n "$erin_line" && -n "$inline_line" && "$erin_line" -lt "$inline_line" ]] \
    || { echo "FAIL: inline comment not grouped under its review" >&2; fail=1; }

# A comment no review claims is still emitted. Dropping it would be the
# silent-data-loss case this section exists to prevent.
expect '## Inline Comments Without a Review (1)'
expect '### @dave — b.sh:9 — 2026-11-04 12:30 — resolved'
expect 'inline two'
grep -qF '_No summary — comments are inline._' "$DISCUSSION" \
    && { echo "FAIL: placeholder survived instead of grouping" >&2; fail=1; }
# The comment is useless without the diff it points at: original line,
# proposed line, and surrounding context all come from diff_hunk verbatim.
expect '```diff'
expect ' context line'
expect '-old line'
expect '+new line'
expect ' more context'
expect '-another old'
expect '+another new'

# --- a failed fetch is visible per source, and costs nothing else ---
GH_API_BROKEN=1 generate_repo_context "$SBX" myrepo personal >/dev/null 2>&1 || true
expect '_Unavailable: gh api repos/org/myrepo/issues/12/comments failed._'
expect '_Unavailable: gh api repos/org/myrepo/pulls/12/reviews failed._'
expect '_Unavailable: gh api repos/org/myrepo/pulls/12/comments failed._'
grep -qF 'desc' "$CTX" || { echo "FAIL: a failed comment fetch lost pr-context.md" >&2; fail=1; }

[[ $fail -eq 0 ]] && echo "all pr-context comment checks passed"
exit $fail
